@tailwind base;
@tailwind components;
@tailwind utilities;

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

@keyframes float {
  0% {
    transform: translateY(100%);
    opacity: 1;
  }
  90% {
    opacity: 1;
  }
  100% {
    transform: translateY(-100vh);
    opacity: 0;
  }
}

@keyframes pop {
  0% {
    transform: scale(1);
    opacity: 1;
  }
  100% {
    transform: scale(0);
    opacity: 0;
  }
}

.bubble {
  animation: float linear forwards;
  cursor: pointer;
  position: absolute;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.5);
}

.bubble.popping {
  animation: pop 0.3s ease-out forwards;
}

.bubble:hover {
  filter: brightness(1.1);
}

import { useState, useEffect, useRef } from 'react'
import './App.css'

const COLORS = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E2']

export default function App() {
  const [bubbles, setBubbles] = useState([])
  const [score, setScore] = useState(0)
  const [gameActive, setGameActive] = useState(true)
  const bubbleIdRef = useRef(0)
  const gameLoopRef = useRef(null)

  // Spawn new bubbles
  useEffect(() => {
    if (!gameActive) return

    gameLoopRef.current = setInterval(() => {
      const newBubble = {
        id: bubbleIdRef.current++,
        x: Math.random() * (window.innerWidth - 80),
        y: window.innerHeight,
        size: Math.random() * 40 + 30, // 30-70px
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
        duration: Math.random() * 3 + 4, // 4-7 seconds to float up
        popping: false,
      }
      setBubbles((prev) => [...prev, newBubble])
    }, 500)

    return () => clearInterval(gameLoopRef.current)
  }, [gameActive])

  // Remove bubbles that have finished floating
  useEffect(() => {
    const interval = setInterval(() => {
      setBubbles((prev) => prev.filter((b) => {
        const elapsed = (Date.now() - (b.spawnTime || Date.now())) / 1000
        return elapsed < b.duration
      }))
    }, 100)

    return () => clearInterval(interval)
  }, [])

  // Handle bubble pop
  const popBubble = (id) => {
    setBubbles((prev) =>
      prev.map((b) =>
        b.id === id ? { ...b, popping: true } : b
      )
    )

    // Calculate points based on bubble size (smaller = more points)
    const bubble = bubbles.find((b) => b.id === id)
    if (bubble) {
      const points = Math.round((70 - bubble.size) / 10 + 1) * 10
      setScore((prev) => prev + points)
    }

    // Remove bubble after animation
    setTimeout(() => {
      setBubbles((prev) => prev.filter((b) => b.id !== id))
    }, 300)
  }

  const toggleGame = () => {
    setGameActive(!gameActive)
  }

  const resetGame = () => {
    setScore(0)
    setBubbles([])
    setGameActive(true)
  }

  return (
    <div className="w-screen h-screen bg-gradient-to-br from-blue-400 via-blue-300 to-cyan-300 overflow-hidden relative flex flex-col">
      {/* Header */}
      <div className="p-4 text-white flex justify-between items-center z-10">
        <h1 className="text-3xl font-bold">Bubble Pop</h1>
        <div className="flex gap-4 items-center">
          <div className="text-2xl font-bold">Score: {score}</div>
          <button
            onClick={toggleGame}
            className="px-4 py-2 bg-white text-blue-500 font-bold rounded-lg hover:bg-gray-100 transition"
          >
            {gameActive ? 'Pause' : 'Resume'}
          </button>
          <button
            onClick={resetGame}
            className="px-4 py-2 bg-red-500 text-white font-bold rounded-lg hover:bg-red-600 transition"
          >
            Reset
          </button>
        </div>
      </div>

      {/* Game Area */}
      <div className="flex-1 relative overflow-hidden">
        {bubbles.map((bubble) => (
          <div
            key={bubble.id}
            className={`bubble ${bubble.popping ? 'popping' : ''}`}
            style={{
              width: `${bubble.size}px`,
              height: `${bubble.size}px`,
              backgroundColor: bubble.color,
              left: `${bubble.x}px`,
              animationDuration: `${bubble.duration}s`,
            }}
            onClick={() => !bubble.popping && popBubble(bubble.id)}
          />
        ))}
      </div>

      {/* Instructions */}
      {bubbles.length === 0 && !gameActive && (
        <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-50 z-20">
          <div className="bg-white p-8 rounded-lg text-center">
            <h2 className="text-2xl font-bold mb-4">Game Paused</h2>
            <p className="text-lg mb-6">Click Resume to continue</p>
          </div>
        </div>
      )}
    </div>
  )
}

